import { faker } from '@faker-js/faker'
import { Avatar, Box, IconButton, Stack, Typography } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import React from 'react'
import StyledBadge from './StyledBadge'
import { ArrowDownLeft, ArrowUpRight, Phone, VideoCamera } from 'phosphor-react'
import { StartAudioCall } from '../redux/slices/audioCall'
import { StartVideoCall } from '../redux/slices/videoCall'
import { useDispatch } from 'react-redux'
import { fDateTime } from '../utils/formatTime';
import truncateString from '../utils/truncate';

const CallLogElement = ({ online, incoming, img, missed, name, id, friend_id, type, startedAt, endedAt }) => {
    const theme = useTheme();
    const dispatch = useDispatch();

    return (
        <Box
            sx={{
                borderRadius: 2,
                backgroundColor: theme.palette.mode === "light" ? "#fff" : theme.palette.background.paper,
                boxShadow: "0 0 10px rgba(0, 0, 0, 0.1)",
                cursor: 'pointer',
                transition: "0.1s ease-in-out", // Smooth transition effect
                '&:hover': {
                    backgroundColor: theme.palette.action.hover, // Change background color on hover
                    transform: 'scale(1.05);',
                },
            }}
            p={2}
        >
            <Stack
                direction='row'
                alignItems={'center'}
                justifyContent='space-between'
            >
                <Stack direction={'row'} alignItems={'center'} spacing={2}>
                    {online ?
                        (
                            <StyledBadge overlap="circular" anchorOrigin={{ vertical: "bottom", horizontal: "right" }} variant="dot">
                                <Avatar src={img} alt={name} />
                            </StyledBadge>
                        ) : (<Avatar src={img} alt={name} />)
                    }

                    <Stack spacing={0.3}>
                        <Typography variant='subtitle2'>{name}</Typography>
                        {/* <Typography variant='caption'>{truncateText(msg, 20)}</Typography> */}
                        <Stack direction={'row'} alignItems={'center'} spacing={1}>
                            {incoming ? <ArrowDownLeft color={missed ? 'red' : 'green'} /> : <ArrowUpRight color={missed ? 'red' : 'green'} />}
                            <Typography variant='caption'>{endedAt ? `${fDateTime(endedAt)}` : `${fDateTime(startedAt)}`}</Typography>
                        </Stack>
                    </Stack>
                </Stack>
                {type === "audio" ? (
                    <IconButton
                        onClick={() => {
                            dispatch(StartAudioCall(friend_id))
                        }}
                    >
                        <Phone color='green' size={20} />
                    </IconButton>
                ) : (
                    <IconButton
                        onClick={() => {
                            dispatch(StartVideoCall(friend_id))
                        }}
                    >
                        <VideoCamera size={20} color='green' />
                    </IconButton>
                )
                }
            </Stack>
        </Box>
    )
}

const CallElement = ({ id, firstName, lastName, avatar, status }) => {
    const dispatch = useDispatch();
    const theme = useTheme();

    return (
        <Box
            sx={{
                borderRadius: 2,
                backgroundColor: theme.palette.mode === "light" ? "#fff" : theme.palette.background.paper,
                boxShadow: "0 0 10px rgba(0, 0, 0, 0.1)",
                cursor: 'pointer',
                transition: "0.1s ease-in-out", // Smooth transition effect
                '&:hover': {
                    backgroundColor: theme.palette.action.hover, // Change background color on hover
                    transform: 'scale(1.05);',
                },
            }}
            p={2}
        >
            <Stack
                direction='row'
                alignItems={'center'}
                justifyContent='space-between'
            >
                <Stack direction={'row'} alignItems={'center'} spacing={2}>
                    {status === "ONLINE" ?
                        (
                            <StyledBadge overlap="circular" anchorOrigin={{ vertical: "bottom", horizontal: "right" }} variant="dot">
                                <Avatar src={avatar} alt={`${firstName} ${lastName}`} />
                            </StyledBadge>
                        ) : (<Avatar src={avatar} alt={`${firstName} ${lastName}`} />)
                    }

                    <Stack spacing={0.3}>
                        <Typography variant='subtitle2'>{`${firstName} ${lastName}`}</Typography>
                    </Stack>
                </Stack>
                <Stack direction={'row'} alignItems={'center'} >
                    <IconButton
                        onClick={() => {
                            dispatch(StartAudioCall(id));
                        }}
                    >
                        <Phone color='green' size={22} />
                    </IconButton>
                    <IconButton
                        onClick={() => {
                            dispatch(StartVideoCall(id));
                        }}
                    >
                        <VideoCamera color='green' size={22} />
                    </IconButton>
                </Stack>
            </Stack>
        </Box>
    )
}

export { CallElement, CallLogElement };